/**
 * Shuffles an array in place using the Fisher-Yates (Knuth) shuffle algorithm.
 * This algorithm ensures that every permutation of the array is equally likely.
 *
 * @param {Array} array - The array to be shuffled.
 * @returns {Array} - The same array, shuffled in place.
 */
function shuffle(array) {
    // Get the length of the array
    const length = array.length;

    // Iterate backwards from the last element to the second element
    for (let i = length - 1; i > 0; i--) {
        // Generate a random index between 0 and i (inclusive)
        const randomIndex = Math.floor(Math.random() * (i + 1));

        // Swap the element at index i with the element at the random index
        const temp = array[i];
        array[i] = array[randomIndex];
        array[randomIndex] = temp;
    }

    // Return the shuffled array (same reference, modified in place)
    return array;
}
